types:
[Node: {} as {
        context: {
          count: number;
        };
        guards:
          | {
              type: 'isGreaterThan';
              params: {
                count: number;
              };
            }
          | { type: 'plainGuard' };
      }]

guard.params:
[Node: ({ context }) => {
              ((_accept: number) => {})(context.count);
              // @ts-expect-error
              ((_accept: 'not any') => {})(context.count);
              return {
                count: context.count
              };
            }]
